n=22
grid=[[0]*n for _ in range(n)]
tiles=[(1,17,2,1),(4,12,2,4),(8,17,2,3),(10,12,2,6),(15,17,2,7),(2,0,8,1),(14,5,8,6),(16,0,8,5)]
for r,c,b,inn in tiles:
    for dr in range(5):
        for dc in range(5):
            grid[r+dr][c+dc]=inn if 1<=dr<=3 and 1<=dc<=3 else b
print('\n'.join(' '.join(map(str,row)) for row in grid))
